using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestMethod]
    [DataRow("5551234567", "(555) 123-4567")]
    [DataRow("8005551212", "(800) 555-1212")]
    public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber(string digits, string expected)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DataRow("5551234567")]
    [DataRow("8005551212")]
    public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens(string digits)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.StartsWith($"({digits[..3]})", result);
    }

    [TestMethod]
    [DataRow("5551234567", "4567")]
    [DataRow("8005551212", "1212")]
    public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits(string digits, string lastFour)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.EndsWith(lastFour, result);
    }

    [TestMethod]
    public void FormatPhoneNumber_ValidDigits_MatchesPhonePattern()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        Assert.MatchesRegex(@"^\(\d{3}\) \d{3}-\d{4}$", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
        Assert.AreEqual("digits", ex.ParamName);
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
        Assert.AreEqual("digits", ex.ParamName);
    }

    [TestMethod]
    [DataRow("Alice", "Mr.", "Dear Mr. Alice,")]
    [DataRow("Bob", "Dr.", "Dear Dr. Bob,")]
    public void BuildGreeting_WithNameAndTitle_ReturnsFullGreeting(string name, string title, string expected)
    {
        var result = _formatter.BuildGreeting(name, title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_StartsWithDearMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.StartsWith("Dear Mr.", result);
    }

    [TestMethod]
    [DataRow("Alice")]
    [DataRow("Smith")]
    public void BuildGreeting_AnyName_EndsWithComma(string name)
    {
        var result = _formatter.BuildGreeting(name);

        Assert.EndsWith(",", result);
    }

    [TestMethod]
    public void BuildGreeting_WithName_ContainsName()
    {
        var result = _formatter.BuildGreeting("Johnson", "Ms.");

        Assert.Contains("Johnson", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_NullOrWhiteSpace_ThrowsArgumentException(string? name)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name!));
    }

    [TestMethod]
    [DataRow("Hello World", "hello-world")]
    [DataRow("My Blog Post!", "my-blog-post")]
    [DataRow("  Spaces Around  ", "spaces-around")]
    public void GenerateSlug_ValidTitle_ReturnsExpectedSlug(string title, string expected)
    {
        var result = _formatter.GenerateSlug(title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void GenerateSlug_ValidTitle_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("Some Title Here!");

        Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GenerateSlug_NullOrWhiteSpace_ThrowsArgumentException(string? title)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(title!));
    }

    [TestMethod]
    [DataRow(9.99, "$", "$9.99")]
    [DataRow(1000, "€", "€1000.00")]
    [DataRow(0, "$", "$0.00")]
    public void FormatCurrency_WithAmountAndSymbol_ReturnsFormattedString(
        double amount, string symbol, string expected)
    {
        var result = _formatter.FormatCurrency((decimal)amount, symbol);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(42.50m);

        Assert.StartsWith("$", result);
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol_StartsWithSymbol()
    {
        var result = _formatter.FormatCurrency(100m, "£");

        Assert.StartsWith("£", result);
    }

    [TestMethod]
    public void FormatCurrency_AnyAmount_EndsWithTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(7m);

        Assert.MatchesRegex(@"\.\d{2}$", result);
        Assert.EndsWith(".00", result);
    }
}

